import{_ as e,o as d,c as l,a2 as o}from"./chunks/framework.Mqs_YBJJ.js";const g=JSON.parse('{"title":"转写文本后处理模式","description":"","frontmatter":{},"headers":[],"relativePath":"text-postprocessing.md","filePath":"text-postprocessing.md","lastUpdated":1787798426000}'),c={name:"text-postprocessing.md"};function a(n,t,i,r,s,x){return d(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="转写文本后处理模式" tabindex="-1">转写文本后处理模式 <a class="header-anchor" href="#转写文本后处理模式" aria-label="Permalink to &quot;转写文本后处理模式&quot;">​</a></h1><p>实时转写和离线转写使用同一组文本后处理模式。离线 JSON 创建任务接口使用 <code>NumberNormalizationMode</code>、<code>FillerFilterMode</code>、<code>ProfanityFilterMode</code>；离线上传接口和实时 WebSocket 使用对应的 snake_case 字段 <code>number_normalization_mode</code>、<code>filler_filter_mode</code>、<code>profanity_filter_mode</code>。两种命名的取值和效果完全相同。</p><p>服务端按“数字转换 → 语气词过滤 → 脏词过滤 → 标点清理”的顺序处理每段识别文本。模式只处理已经识别出的文字，不会改变音频识别过程。以下表格列出的值是客户端可依赖的受支持取值；请勿传入其它整数。</p><h2 id="数字转换模式" tabindex="-1">数字转换模式 <a class="header-anchor" href="#数字转换模式" aria-label="Permalink to &quot;数字转换模式&quot;">​</a></h2><p><code>number_normalization_mode</code> / <code>NumberNormalizationMode</code> 控制中文数字表达是否转换为阿拉伯数字等书面形式。</p><table tabindex="0"><thead><tr><th style="text-align:center;">模式</th><th style="text-align:left;">名称</th><th style="text-align:left;">行为</th></tr></thead><tbody><tr><td style="text-align:center;"><code>0</code></td><td style="text-align:left;">不转换</td><td style="text-align:left;">不执行数字转换，保留模型识别出的中文数字文本。</td></tr><tr><td style="text-align:center;"><code>1</code></td><td style="text-align:left;">智能转换（默认）</td><td style="text-align:left;">按上下文保守转换高置信度数字表达，包括编号、日期、时间、百分比、金额与常见计量单位、序数、道路/房间号，以及“洞、幺、两、拐、勾”等通信数字读法；会保护可能表示约数、固定词语或专名的表达，降低误转风险。</td></tr><tr><td style="text-align:center;"><code>3</code></td><td style="text-align:left;">数学与数字串增强转换</td><td style="text-align:left;">包含模式 <code>1</code> 的规则，并额外转换分数、数学运算上下文，以及更像逐位读数的混合数字串。适合公式、口述编号等希望更积极转换数字的场景。</td></tr></tbody></table><p>典型效果：</p><table tabindex="0"><thead><tr><th style="text-align:left;">输入文本</th><th style="text-align:left;">模式 <code>0</code></th><th style="text-align:left;">模式 <code>1</code></th><th style="text-align:left;">模式 <code>3</code></th></tr></thead><tbody><tr><td style="text-align:left;"><code>二零二六年四月十六日十五点三十分支付五百二十元</code></td><td style="text-align:left;">原样保留</td><td style="text-align:left;"><code>2026年4月16日15:30支付520元</code></td><td style="text-align:left;">同模式 <code>1</code></td></tr><tr><td style="text-align:left;"><code>订单号二零二六零四一六零零一</code></td><td style="text-align:left;">原样保留</td><td style="text-align:left;"><code>订单号20260416001</code></td><td style="text-align:left;">同模式 <code>1</code></td></tr><tr><td style="text-align:left;"><code>警号洞幺两三四五六拐八勾</code></td><td style="text-align:left;">原样保留</td><td style="text-align:left;"><code>警号0123456789</code></td><td style="text-align:left;">同模式 <code>1</code></td></tr><tr><td style="text-align:left;"><code>三分之一加负五点二等于二</code></td><td style="text-align:left;">原样保留</td><td style="text-align:left;">原样保留</td><td style="text-align:left;"><code>1/3加-5.2等于2</code></td></tr><tr><td style="text-align:left;"><code>四二十六分</code>（逐位读数）</td><td style="text-align:left;">原样保留</td><td style="text-align:left;">原样保留</td><td style="text-align:left;"><code>4216分</code></td></tr><tr><td style="text-align:left;"><code>三四天后参加五四运动</code></td><td style="text-align:left;">原样保留</td><td style="text-align:left;">原样保留</td><td style="text-align:left;">原样保留</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>数字转换采用上下文规则而不是无条件替换。模式 <code>3</code> 比模式 <code>1</code> 更积极，但仍会保留已知固定表达和明显约数；它不等同于“把所有中文数字字符逐字替换”。</p></div><h2 id="语气词过滤模式" tabindex="-1">语气词过滤模式 <a class="header-anchor" href="#语气词过滤模式" aria-label="Permalink to &quot;语气词过滤模式&quot;">​</a></h2><p><code>filler_filter_mode</code> / <code>FillerFilterMode</code> 控制是否删除口语中的语气词和话语填充词。</p><table tabindex="0"><thead><tr><th style="text-align:center;">模式</th><th style="text-align:left;">名称</th><th style="text-align:left;">行为</th></tr></thead><tbody><tr><td style="text-align:center;"><code>0</code></td><td style="text-align:left;">不过滤（默认）</td><td style="text-align:left;">保留全部语气词。</td></tr><tr><td style="text-align:center;"><code>1</code></td><td style="text-align:left;">基础过滤</td><td style="text-align:left;">删除短语气词：<code>嗯</code>、<code>呃</code>、<code>额</code>、<code>啊</code>、<code>哦</code>、<code>唉</code>、<code>诶</code>、<code>欸</code>、<code>嗯嗯</code>、<code>呃呃</code>。</td></tr><tr><td style="text-align:center;"><code>2</code></td><td style="text-align:left;">扩展过滤</td><td style="text-align:left;">删除模式 <code>1</code> 的词，并额外删除独立出现的常见填充短语：<code>那个</code>、<code>这个</code>、<code>就是说</code>、<code>就是</code>、<code>然后</code>、<code>你知道</code>、<code>对吧</code>、<code>是吧</code>、<code>怎么说</code>、<code>怎么说呢</code>。</td></tr></tbody></table><p>示例输入：<code>嗯，我们，那个，方案，就是说，再确认。</code></p><table tabindex="0"><thead><tr><th style="text-align:center;">模式</th><th style="text-align:left;">输出</th></tr></thead><tbody><tr><td style="text-align:center;"><code>0</code></td><td style="text-align:left;"><code>嗯，我们，那个，方案，就是说，再确认。</code></td></tr><tr><td style="text-align:center;"><code>1</code></td><td style="text-align:left;"><code>我们，那个，方案，就是说，再确认。</code></td></tr><tr><td style="text-align:center;"><code>2</code></td><td style="text-align:left;"><code>我们，方案，再确认。</code></td></tr></tbody></table><p>基础短语气词紧邻中文正文时也可以被删除；模式 <code>2</code> 新增的多字填充短语只在句首、句尾或空格/标点分隔的短语边界上匹配，避免误删正常词组中的相同文字。删除后服务端会执行通用标点清理，包括合并相邻重复标点，以及清理由删除操作留下的部分句首或句尾逗号。</p><h2 id="脏词过滤模式" tabindex="-1">脏词过滤模式 <a class="header-anchor" href="#脏词过滤模式" aria-label="Permalink to &quot;脏词过滤模式&quot;">​</a></h2><p><code>profanity_filter_mode</code> / <code>ProfanityFilterMode</code> 控制命中内置脏词表后的输出方式。</p><table tabindex="0"><thead><tr><th style="text-align:center;">模式</th><th style="text-align:left;">名称</th><th style="text-align:left;">行为</th></tr></thead><tbody><tr><td style="text-align:center;"><code>0</code></td><td style="text-align:left;">不过滤（默认）</td><td style="text-align:left;">保留命中的脏词原文。</td></tr><tr><td style="text-align:center;"><code>1</code></td><td style="text-align:left;">删除</td><td style="text-align:left;">删除命中的完整脏词。</td></tr><tr><td style="text-align:center;"><code>2</code></td><td style="text-align:left;">遮盖</td><td style="text-align:left;">将每个命中的完整脏词替换为一个半角星号 <code>*</code>，不按原词字数重复星号。</td></tr></tbody></table><p>示例输入：<code>这也太妈的离谱了。</code></p><table tabindex="0"><thead><tr><th style="text-align:center;">模式</th><th style="text-align:left;">输出</th></tr></thead><tbody><tr><td style="text-align:center;"><code>0</code></td><td style="text-align:left;"><code>这也太妈的离谱了。</code></td></tr><tr><td style="text-align:center;"><code>1</code></td><td style="text-align:left;"><code>这也太离谱了。</code></td></tr><tr><td style="text-align:center;"><code>2</code></td><td style="text-align:left;"><code>这也太*离谱了。</code></td></tr></tbody></table><p>脏词按内置词表进行完整词条匹配；同一位置可能匹配多个词条时优先处理最长词条。当前词表主要覆盖常见中文辱骂表达，词表可能随服务版本扩充。需要保留逐字稿原貌时使用模式 <code>0</code>；需要可见地标记过滤位置时使用模式 <code>2</code>。</p>',21)])])}const f=e(c,[["render",a]]);export{g as __pageData,f as default};
